#include <iostream>
#include <vector>
#include <algorithm>
#include <queue>

using namespace std;

int d, n;
vector<int> a, e, r;
vector<vector<int>> memo;

const int INF = 1000000000;

void iterative_rec() {
    queue<pair<int, pair<int, int>>> q; // holds (c, (exp, end))
    q.push({0, {0, d}});
    memo[0][d] = 0;

    while (!q.empty()) {
        auto [c, exp_end] = q.front();
        q.pop();
        int exp = exp_end.first;
        int end = exp_end.second;

        for (int i = 0; i < n; i++) {
            if (exp < r[i]) continue;
            int new_exp = min(exp + e[i], 100);
            int new_end = max(end - a[i], 0);
            if (memo[new_exp][new_end] > c + 1) {
                memo[new_exp][new_end] = c + 1;
                q.push({c + 1, {new_exp, new_end}});
            }
        }
    }
}

int main() {
    while (cin >> d >> n, d) {
        a = e = r = vector<int>(n);
        for (int i = 0; i < n; i++) cin >> a[i] >> e[i] >> r[i];
        memo = vector<vector<int>>(105, vector<int>(105, INF));
        iterative_rec();
        int ans = INF;
        for (int i = 0; i < 101; i++) ans = min(ans, memo[i][0]);
        cout << (ans == INF ? "NA" : to_string(ans)) << endl;
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int d, n;
vector<int> a, e, r;
vector<vector<int>> dp;

const int INF = 1000000000;

int main() {
    while (cin >> d >> n, d) {
        a = e = r = vector<int>(n);
        for (int i = 0; i < n; i++) cin >> a[i] >> e[i] >> r[i];

        dp = vector<vector<int>>(105, vector<int>(105, INF));
        dp[0][d] = 0; // Starting point

        for (int exp = 0; exp <= 100; exp++) {
            for (int end = 0; end <= d; end++) {
                if (dp[exp][end] == INF) continue;
                for (int i = 0; i < n; i++) {
                    if (exp < r[i]) continue;
                    int newExp = min(exp + e[i], 100);
                    int newEnd = max(end - a[i], 0);
                    dp[newExp][newEnd] = min(dp[newExp][newEnd], dp[exp][end] + 1);
                }
            }
        }

        int ans = INF;
        for (int i = 0; i < 101; i++) ans = min(ans, dp[i][0]);
        cout << (ans == INF ? "NA" : to_string(ans)) << endl;
    }
    return 0;
}

